729		<script>
730			const themeToggle = document.getElementById('theme-toggle');
731			const htmlElement = document.documentElement;
732			const prefersDark = window.matchMedia('(prefers-color-scheme: dark)');
733	
734			const themeColors = { light: '#ffffff', dark: '#121212' };
735			const themeColorMetas = document.querySelectorAll('meta[name="theme-color"]');
736			themeColorMetas.forEach((meta) => {
737				meta.dataset.defaultContent = meta.content;
738			});
739	
740			const updateThemeUI = () => {
741				const forced = htmlElement.dataset.theme;
742				const isDark = forced ? forced === 'dark' : prefersDark.matches;
743				const label = isDark ? 'Switch to light mode' : 'Switch to dark mode';
744				themeToggle.textContent = isDark ? '☀️' : '🌙';
745				themeToggle.setAttribute('aria-label', label);
746				themeToggle.title = label;
747				themeColorMetas.forEach((meta) => {
748					meta.content = forced ? themeColors[forced] : meta.dataset.defaultContent;
749				});
750			};
751	
752			if (themeToggle) {
753				themeToggle.hidden = false;
754				updateThemeUI();
755	
756				themeToggle.addEventListener('click', () => {
757					const systemTheme = prefersDark.matches ? 'dark' : 'light';
758					const current = htmlElement.dataset.theme || systemTheme;
759					const next = current === 'dark' ? 'light' : 'dark';
760					// Choosing the system theme clears the override so the page follows the OS again.
761					try {
762						if (next === systemTheme) {
763							delete htmlElement.dataset.theme;
764							localStorage.removeItem('theme');
765						} else {
766							htmlElement.dataset.theme = next;
767							localStorage.setItem('theme', next);
768						}
769					} catch {}
770					updateThemeUI();
771				});
772	
773				prefersDark.addEventListener('change', () => {
774					if (!htmlElement.dataset.theme) {
775						updateThemeUI();
776					}
777				});
778	
779				// Keep other open tabs in step with the choice made in this one.
780				window.addEventListener('storage', (event) => {
781					if (event.key !== null && event.key !== 'theme') {
782						return;
783					}
784					if (event.newValue === 'light' || event.newValue === 'dark') {
785						htmlElement.dataset.theme = event.newValue;
786					} else {
787						delete htmlElement.dataset.theme;
788					}
789					updateThemeUI();
790				});
791			}
792	
793			const copyrightYear = document.getElementById('copyright-year');
794			if (copyrightYear) {
795				copyrightYear.textContent = String(new Date().getFullYear());
796			}
797	
798			const messages = [
799				"This update was announced to screen readers!",
800				"Dynamic content updates work with aria-live regions.",
801				"Live regions are essential for accessible web apps.",
802				"Try this with a screen reader like NVDA or JAWS!"
803			];
804			let nextMessage = 0;
805			let count = 0;
806			const announceBtn = document.getElementById('announce');
807			const liveMessage = document.getElementById('live-message');
808			const contactForm = document.getElementById('contact-form');
809			const emailInput = document.getElementById('email');
810			const messageInput = document.getElementById('message');
811			const messageCount = document.getElementById('message-count');
812			const messageCountStatus = document.getElementById('message-count-status');
813			const formStatus = document.getElementById('form-status');
814			const countDisplay = document.getElementById('count');
815			const countMessage = document.getElementById('count-message');
816			const decreaseBtn = document.getElementById('decrease');
817			const increaseBtn = document.getElementById('increase');
818			const resetBtn = document.getElementById('reset');
819	
820			const updateCountDisplay = () => {
821				countDisplay.textContent = String(count);
822				countMessage.textContent = `Count is ${count}.`;
823			};
824	
825			if (countDisplay && countMessage) {
826				decreaseBtn?.addEventListener('click', () => {
827					count--;
828					updateCountDisplay();
829				});
830	
831				increaseBtn?.addEventListener('click', () => {
832					count++;
833					updateCountDisplay();
834				});
835	
836				resetBtn?.addEventListener('click', () => {
837					count = 0;
838					updateCountDisplay();
839				});
840			}
841	
842			if (announceBtn && liveMessage) {
843				announceBtn.addEventListener('click', () => {
844					liveMessage.textContent = messages[nextMessage];
845					nextMessage = (nextMessage + 1) % messages.length;
846				});
847			}
848	
849			if (contactForm) {
850				const emailError = document.getElementById('email-error');
851				const submitBtn = contactForm.querySelector('button[type="submit"]');
852				const isSending = () => submitBtn.getAttribute('aria-disabled') === 'true';
853	
854				// Set here rather than in the markup so native validation still works without JavaScript.
855				contactForm.noValidate = true;
856	
857				const setFormStatus = (message, state) => {
858					formStatus.textContent = message;
859					if (state) {
860						formStatus.dataset.state = state;
861					} else {
862						delete formStatus.dataset.state;
863					}
864				};
865	
866				const countThresholds = [0, 10, 25, 50, 100];
867				let lastThreshold;
868	
869				const updateMessageCount = () => {
870					if (messageInput && messageCount) {
871						const remaining = messageInput.maxLength - messageInput.value.length;
872						// Match the page language rather than the browser locale.
873						messageCount.textContent = remaining.toLocaleString(htmlElement.lang);
874						// Announce only when a threshold is crossed, not on every keystroke.
875						const threshold = countThresholds.find((limit) => remaining <= limit);
876						if (messageCountStatus && threshold !== lastThreshold) {
877							lastThreshold = threshold;
878							messageCountStatus.textContent = threshold === undefined
879								? ''
880								: `${remaining.toLocaleString(htmlElement.lang)} characters remaining.`;
881						}
882					}
883				};
884	
885				messageInput?.addEventListener('input', updateMessageCount);
886				// Browsers may restore field values on back/forward navigation.
887				window.addEventListener('pageshow', updateMessageCount);
888				updateMessageCount();
889	
890				const setEmailError = (message) => {
891					emailError.textContent = message;
892					if (message) {
893						emailInput.setAttribute('aria-invalid', 'true');
894						emailInput.setAttribute('aria-describedby', 'email-error email-help');
895					} else {
896						emailInput.removeAttribute('aria-invalid');
897						emailInput.setAttribute('aria-describedby', 'email-help');
898					}
899				};
900	
901				const validateEmail = () => {
902					let message = '';
903					if (emailInput.validity.valueMissing) {
904						message = 'Email address is required.';
905					} else if (emailInput.validity.typeMismatch) {
906						message = 'Please enter a valid email address (e.g., name@example.com).';
907					} else if (!emailInput.validity.valid) {
908						message = 'Please enter a valid email address.';
909					}
910					setEmailError(message);
911					return !message;
912				};
913	
914				emailInput.addEventListener('blur', () => {
915					if (emailInput.value || emailInput.hasAttribute('aria-invalid')) {
916						validateEmail();
917					}
918				});
919	
920				emailInput.addEventListener('input', () => {
921					if (emailInput.hasAttribute('aria-invalid')) {
922						validateEmail();
923					}
924				});
925	
926				contactForm.addEventListener('input', () => {
927					if (!isSending()) {
928						setFormStatus('');
929					}
930				});
931	
932				contactForm.addEventListener('submit', async (event) => {
933					event.preventDefault();
934					if (isSending()) {
935						return;
936					}
937					setFormStatus('');
938					if (!validateEmail()) {
939						setFormStatus('Please correct the errors above before submitting.', 'error');
940						emailInput.focus();
941						return;
942					}
943					const originalText = submitBtn.textContent;
944					submitBtn.setAttribute('aria-disabled', 'true');
945					submitBtn.setAttribute('aria-busy', 'true');
946					submitBtn.textContent = 'Sending…';
947					setFormStatus('Sending your message…', 'pending');
948					emailInput.readOnly = true;
949					if (messageInput) messageInput.readOnly = true;
950					await new Promise(resolve => setTimeout(resolve, 800));
951					emailInput.readOnly = false;
952					if (messageInput) messageInput.readOnly = false;
953					contactForm.reset();
954					setEmailError('');
955					updateMessageCount();
956					submitBtn.removeAttribute('aria-disabled');
957					submitBtn.removeAttribute('aria-busy');
958					submitBtn.textContent = originalText;
959					setFormStatus('Success! Thanks for your message. This is a demo, so nothing was sent.');
960					emailInput.focus();
961				});
962			}
963		</script>
